  /// Find matching country by code, English name, Turkish name, or partial search query
  static TravelCountry? matchCountry(String query) {
    if (query.trim().isEmpty) return null;
    final q = query.trim().toLowerCase();

    // 1. Direct 2-letter ISO code match (e.g. "TR", "IT", "JP")
    for (final c in allCountries) {
      if (c.code.toLowerCase() == q) return c;
    }

    // 2. Direct exact name match (Turkish or English)
    for (final c in allCountries) {
      if (c.nameTr.toLowerCase() == q || c.nameEn.toLowerCase() == q) return c;
    }

    // 3. Substring / contains match (e.g. "İtalya Gezisi", "Tokyo, Japan", "Roma")
    for (final c in allCountries) {
      final nameTrLow = c.nameTr.toLowerCase();
      final nameEnLow = c.nameEn.toLowerCase();
      if (q.contains(nameTrLow) ||
          q.contains(nameEnLow) ||
          nameTrLow.contains(q) ||
          nameEnLow.contains(q)) {
        return c;
      }
    }

    return null;
  }
